class IncompleteOriginalBattle(RuntimeError):pass


def report(env=None,formation=None):
    result=dict(schema='battle-restoration-fidelity-v1',exact_gameplay=False,
        systems=[dict(id=key,status=status,scope=scope) for key,status,scope in SYSTEMS],
        remaining_full_battle_gates=[key for key,status,_ in SYSTEMS if status!='verified_primitive'],
        percentage=None,percentage_reason='No complete original replay corpus or weighted branch-coverage baseline exists')
    if env is not None:
        result['profile']=env.rules.name
        result['deployment_profile']=getattr(env,'deployment_profile',None)
        result['counter_exchange']=getattr(env,'counter_exchange',None)
        result['counter_policy_profile']=getattr(env,'counter_policy_profile',None)
        result['support_policy_profile']=getattr(env,'support_policy_profile',None)
        result['weapon_debuff_profile']=getattr(env,'weapon_debuff_profile',None)
        result['map_target_profile']=getattr(env,'map_target_profile',None)
        result['map_range_profile']=getattr(env,'map_range_profile',None)
        result['map_execution_plan_profile']=getattr(env,'map_execution_plan_profile',None)
        result['map_result_profile']=getattr(env,'map_result_profile',None)
        result['map_attack_profile']=getattr(env,'map_attack_profile',None)
        result['map_weapon_data_profile']=getattr(env,'map_weapon_data_profile',None)
        result['map_context_profile']=getattr(env,'map_context_profile',None)
        result['map_cost_profile']=getattr(env,'map_cost_profile',None)
        result['map_availability_profile']=getattr(env,'map_availability_profile',None)
        result['map_moving_profile']=getattr(env,'map_moving_profile',None)
        result['map_destination_profile']=getattr(env,'map_destination_profile',None)
        result['map_terrain_profile']=getattr(env,'map_terrain_profile',None)
        result['active_weapon_debuffs']=sum(len(u.get('active_weapon_debuffs',[])) for u in env.units.values())
        result['character_skills']=dict(action_count=len(getattr(env,'skill_action_catalog',[])),
            active_timed_effects=sum(len(u.get('active_skill_effects',[])) for u in env.units.values()),
            pending_count=sum(len(u.get('pending_character_skills',[])) for u in env.units.values()))
        result['support_exchange']=getattr(env,'support_exchange',None)
        result['support_defense']=getattr(env,'support_defense',None)
        result['passives']=dict(active=sum(len(u.get('applied_passive_ids',[])) for u in env.units.values()),
            battle_time_registered=sum(len(u.get('combat_traits',[])) for u in env.units.values()),
            inactive=sum(len(u.get('inactive_passive_ids',[])) for u in env.units.values()),
            pending=sum(len(u.get('pending_passives',[])) for u in env.units.values()),
            pending_reasons=dict(Counter(t['reason'] for u in env.units.values() for t in u.get('pending_passives',[]))))
        clock=getattr(env,'phase_clock',None)
        result['stage_clock']=(dict(kind='original-standard',max_turns=env.max_turns,
            side=clock.side,turn=clock.turn,transitions=clock.transitions,original_turn_clock=True,
            stage_outcome_profile='kill-all-turn-count-subset' if hasattr(env,'stage_outcome_runtime') else None,
            original_win_lose_event_timing=False) if clock else dict(kind='experimental',max_phases=env.max_turns,
            original_turn_clock=False,original_win_lose_event_timing=False))
        result['supporters']=dict(applied_effects=sum(len(u.get('supporter_effects',[])) for u in env.units.values()),
            inactive_contents=sum(len(u.get('inactive_supporter_effects',[])) for u in env.units.values()),
            pending_contents=sum(len(u.get('pending_supporter_effects',[])) for u in env.units.values()),
            active_skills_executed=False)
    if formation is not None:
        slots=[s for f in formation['forces'] for s in f['slots']]
        result['formation']=dict(units=len(slots),supporters=sum(len(f['supporters']) for f in formation['forces']),
            terrain_source_units=sum('terrain_capability_sources' in s for s in slots),
            equipped_parts=sum(bool(s['option_parts_id']) for s in slots),
            weapon_definitions=sum(len(s['weapons']) for s in slots),
            pending_weapon_definitions=sum(len(s['pending_weapons']) for s in slots),
            character_skill_definitions=sum(len(s['character_skill_configuration']) for s in slots))
    return result


def require_complete_original(env=None,formation=None):
    evidence=report(env,formation)
    if not evidence['exact_gameplay']:
        raise IncompleteOriginalBattle('Full original battle unavailable; incomplete systems: '+
                                      ', '.join(evidence['remaining_full_battle_gates']))
    return evidence
